  // ------------------------------------------------------------------ THE ENGINEER (hero character, world px; origin = seat point)
  /** st: {look:[x,y], turn, sink (0..1 head squash), lid, mouth open, brow, typing(bool), laptop (bool), sleep (lying pose handled elsewhere), t} */
