    const t = st.t || 0; const tt = twos(t); ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    const skin = '#E0A57E', hood = '#8E949D', hoodD = '#5f6470', pants = '#4E5872', beard = '#3B2A22', hairC = '#2E211B';
    const breath = Math.sin(t * 1.7) * 3; const sink = st.sink || 0; const typ = st.typing ? Math.sin(tt * 26) * 2 : 0;
    const lw = 4;
    // legs crossed (lotus)
    const legs = SM([[-70, -150], [-205, -95], [-248, -30], [-205, 18], [-40, 30], [60, 30], [205, 18], [248, -30], [205, -95], [70, -150]]);
    S8.cel(ctx, legs, { fill: pants, s: 16, lw, rim: '#8c97b6', shade: '#323a52' });
