    const mus = SM([[fx - 50, 56], [fx - 20, 40], [fx, 46], [fx + 20, 40], [fx + 50, 56], [fx + 30, 62], [fx, 56], [fx - 30, 62]]); S8.cel(ctx, mus, { fill: beard, s: 4, lw: 3, shade: '#22160f' });
