    ctx.save(); ctx.strokeStyle = '#141014'; ctx.lineWidth = 9; ctx.beginPath(); ctx.roundRect(fx - 76, -62, 66, 54, 14); ctx.roundRect(fx + 10, -62, 66, 54, 14); ctx.moveTo(fx - 10, -40); ctx.quadraticCurveTo(fx, -48, fx + 10, -40); ctx.moveTo(fx - 76, -45); ctx.lineTo(-90, -40); ctx.moveTo(fx + 76, -45); ctx.lineTo(90, -40); ctx.stroke(); ctx.globalCompositeOperation = 'screen'; ctx.fillStyle = st.glow || 'rgba(170,210,255,0.28)'; ctx.fill(S8.rr(fx - 72, -58, 58, 46, 11)); ctx.fill(S8.rr(fx + 14, -58, 58, 46, 11)); ctx.fillStyle = 'rgba(255,255,255,0.55)'; ctx.beginPath(); ctx.moveTo(fx - 66, -54); ctx.lineTo(fx - 50, -54); ctx.lineTo(fx - 64, -22); ctx.closePath(); ctx.moveTo(fx + 20, -54); ctx.lineTo(fx + 36, -54); ctx.lineTo(fx + 22, -22); ctx.fill(); ctx.restore();
