    const ph = st.walk ? tt * 9 : 0; const bob = st.walk ? Math.abs(Math.sin(ph)) * -14 : 0; const sway = st.walk ? Math.sin(ph) * 0.03 : 0;
    ctx.translate(0, bob); ctx.rotate(sway + (st.lean || 0));
    // slippers + calves
    for (const sg of [-1, 1]) { const stp = st.walk ? Math.sin(ph + (sg > 0 ? Math.PI : 0)) * 30 : 0; const lift = st.walk ? Math.max(0, Math.sin(ph + (sg > 0 ? Math.PI : 0))) * 16 : 0; const cx = sg * 52 + stp * -1;
      S8.cel(ctx, SM([[cx - 22, -230], [cx + 22, -230], [cx + 20, -60], [cx + 14, -20 - lift], [cx - 14, -20 - lift], [cx - 22, -60]]), { fill: skin, s: 6, lw: 3.5, shade: '#b97a5a' });
      S8.cel(ctx, SM([[cx - 30, -30 - lift], [cx + 40, -36 - lift], [cx + 56, -14 - lift], [cx + 40, 4 - lift], [cx - 34, 4 - lift]]), { fill: '#E99AA8', s: 6, lw: 3.5, rim: '#FFD3DB', shade: '#b56676', after: (c) => { c.fillStyle = 'rgba(255,240,245,0.65)'; c.beginPath(); c.ellipse(cx + 10, -30 - lift, 30, 10, 0, 0, MG.TAU); c.fill(); } }); }
    // dress (A-line house dress) with flowers
    const body = SM([[-60, -650], [-120, -620], [-140, -560], [-150, -440], [-175, -300], [-185, -200], [0, -180], [185, -200], [175, -300], [150, -440], [140, -560], [120, -620], [60, -650]]);
    S8.cel(ctx, body, { fill: dress, s: 22, lw, rim: '#C8B0DC', rimW: 7, shade: dressD, after: (c) => { const rr = MG.rng(17); for (let k = 0; k < 46; k++) { const px = -170 + rr() * 340, py = -640 + rr() * 450; c.fillStyle = ['#F4EEE2', '#F6D06F', '#F0735A'][k % 3]; for (let q = 0; q < 5; q++) { const a = q / 5 * MG.TAU; c.beginPath(); c.arc(px + Math.cos(a) * 6, py + Math.sin(a) * 6, 4.5, 0, MG.TAU); c.fill(); } c.fillStyle = '#E07B24'; c.beginPath(); c.arc(px, py, 3, 0, MG.TAU); c.fill(); } } });
    // apron
    S8.cel(ctx, SM([[-95, -470], [95, -470], [110, -230], [0, -215], [-110, -230]]), { fill: '#F3EEE4', s: 10, lw: 3.5, shade: '#c9bfae', after: (c) => { c.strokeStyle = 'rgba(31,78,140,0.35)'; c.lineWidth = 6; for (let k = 0; k < 8; k++) { c.beginPath(); c.moveTo(-120, -460 + k * 32); c.lineTo(120, -460 + k * 32); c.stroke(); } } });
    S8.cel(ctx, S8.rr(-60, -380, 120, 70, 12), { fill: '#EAE3D6', s: 4, lw: 3 });
    // arms
    const reach = st.reach || 0;
    const armPts = (sg, ang, bend) => { const sx = sg * 125, sy = -610; const ex = sx + sg * Math.sin(ang) * 150, ey = sy + Math.cos(ang) * 150; const wx = ex + sg * Math.sin(ang + bend) * 140, wy = ey + Math.cos(ang + bend) * 140; return [[sx, sy], [ex, ey], [wx, wy]]; };
    const drawArm = (pts, hold) => { S8.stroke(ctx, pts, 64, INK); S8.stroke(ctx, pts, 56, skin); S8.stroke(ctx, pts.slice(0, 2).map((p, i) => i ? [lerp(pts[0][0], p[0], 0.6), lerp(pts[0][1], p[1], 0.6)] : p), 74, INK); S8.stroke(ctx, pts.slice(0, 2).map((p, i) => i ? [lerp(pts[0][0], p[0], 0.6), lerp(pts[0][1], p[1], 0.6)] : p), 66, dress); const w = pts[2]; ctx.save(); ctx.translate(w[0], w[1]); const ang = Math.atan2(w[1] - pts[1][1], w[0] - pts[1][0]); K.hand(ctx, 0, 0, { pose: hold || 'open', angle: ang - Math.PI / 2, s: 1.25, skin, outline: INK }); ctx.restore(); return w; };
