    drawArm(armPts(1, st.basket !== false ? 0.35 : 0.2, st.basket !== false ? -1.25 : 0.1), 'fist');
    // head
    ctx.save(); const hy = -770; ctx.translate(st.turn ? st.turn * 10 : 0, hy + (st.talk ? Math.sin(tt * 20) * 3 : 0)); const turn = st.turn ?? -0.4;
    const neck = S8.rr(-34, 60, 68, 70, 20); S8.cel(ctx, neck, { fill: skin, s: 6, lw: 3 });
