      const sink = MG.jiggle(t, 1192.95, 1, 1.6, 3.2) > 0 ? MG.jiggle(t, 1192.95, 0.5, 1.6, 3.2) + 0.25 * PR(t, 1192.9, 1193.1) : 0.25 * PR(t, 1192.9, 1193.1) * (1 - PR(t, 1193.6, 1194.2));
      ctx.save(); ctx.filter = 'blur(26px)'; ctx.fillStyle = 'rgba(60,30,70,0.22)'; ctx.beginPath(); ctx.ellipse(R.eng[0] + 70, R.eng[1] - 260, 230, 300, 0, 0, MG.TAU); ctx.fill(); ctx.restore();
      S8.engineer(ctx, R.eng[0], R.eng[1], 1, { t, turn, sink, look, typing: t < 1190.95 || t > 1194, brow: t > TW('engineering', 1190.2) && t < 1191 ? 0.6 : 0, lid: t > 1191.6 && t < 1193.0 ? 0.25 : 0.42, mouth: t > 1192.2 && t < 1192.6 ? 0.2 : 0 });
