        const reach = t < 1192.45 ? 0 : PR(t, 1192.45, 1192.8); const pat = t > 1192.8 && t < 1193.25;
        S8.contact(ctx, mx, 1705, 170, 26, 0.35);
        S8.mum(ctx, mx, 1700, 1.02, { t, walk: walking, reach: Math.min(reach, 1) * 0.86 + (pat ? 0.04 : 0), pat, talk: t > 1191.4 && t < 1193.3, turn: -0.55, look: [-0.8, -0.3], basketN: t > 1192.3 ? 2 : 3, lean: reach * -0.06 });
