      const gl = MG.win(t, TW('engineering', 1190.2) - 0.05, TW('degree', 1190.6) + 0.45, 0.15, 0.3); if (gl > 0) { ctx.save(); ctx.beginPath(); ctx.rect(1890, 430, 300, 230); ctx.clip(); ctx.globalCompositeOperation = 'screen'; const gx = lerp(1850, 2250, LIN(t, TW('engineering', 1190.2) - 0.05, TW('degree', 1190.6) + 0.45)); const g = ctx.createLinearGradient(gx - 60, 430, gx + 60, 660); g.addColorStop(0, 'rgba(255,240,200,0)'); g.addColorStop(0.5, `rgba(255,240,200,${0.8 * gl})`); g.addColorStop(1, 'rgba(255,240,200,0)'); ctx.fillStyle = g; ctx.fillRect(1850, 400, 400, 300); ctx.restore(); }
