      ctx.save(); ctx.beginPath(); ctx.rect(XL, -600, XR - XL, FL + 600); ctx.clip(); MG.fx.particles(ctx, { n: 40, seed: 12, t, area: [XL, 300, XR - XL, 1500], vel: [4, -8], life: 6, size: [1.5, 3.5], color: '#ffffff', alpha: 0.7, drift: 25 }); ctx.restore();
