      // Spanish side: hook with a kid backpack AND a grown man's jacket ; Swedish side: an empty hook
      S8.hook(ctx, 330, 1180); ctx.save(); ctx.translate(280, 1200); S8.cel(ctx, SM([[-40, 0], [40, 0], [70, 160], [50, 320], [-50, 320], [-70, 160]]), { fill: '#4E5872', s: 10, lw: 3.5, shade: '#323a52' }); ctx.restore(); ctx.save(); ctx.translate(385, 1220); S8.cel(ctx, S8.rr(-50, 0, 100, 130, 22), { fill: '#C8423B', s: 8, lw: 3.5, after: (x) => { x.fillStyle = '#F6D06F'; x.beginPath(); x.arc(0, 60, 16, 0, MG.TAU); x.fill(); } }); ctx.restore();
      S8.hook(ctx, 2140, 1180, { wood: '#D8C29A' });
