  S8.cobbles = () => MG.cache('s08:cobbles', 1920, 1080, (x) => { MG.fx.vgrad(x, [[0, '#F6C98C'], [0.5, '#F8DDB0'], [0.62, '#E9C08E'], [1, '#8a6a58']]); const hz = 640; x.fillStyle = '#9A8070'; x.fillRect(0, hz, 1920, 440); const rr = MG.rng(4); for (let j = 0; j < 26; j++) { const v0 = j / 26, v1 = (j + 1) / 26; const y0 = hz + Math.pow(v0, 2.2) * 440, y1 = hz + Math.pow(v1, 2.2) * 440; const sc = 0.15 + Math.pow(v0, 2.2) * 2.4; const bw = 70 * sc; for (let i = -2; i < 1920 / bw + 2; i++) { const bx = i * bw + (j % 2) * bw * 0.5 - (960 % bw); const p = SM([[bx + 3, y0 + 2], [bx + bw - 3, y0 + 2 + rr() * 2], [bx + bw - 2, y1 - 2], [bx + 2, y1 - 2]]); x.fillStyle = MG.col.mix('#8f7868', '#c0a894', rr()); x.fill(p); x.fillStyle = 'rgba(255,230,190,0.25)'; x.fillRect(bx + 4, y0 + 2, bw * 0.5, Math.max(1, (y1 - y0) * 0.2)); } } const g = x.createLinearGradient(0, hz, 0, 1080); g.addColorStop(0, 'rgba(255,200,140,0.45)'); g.addColorStop(0.3, 'rgba(255,200,140,0)'); g.addColorStop(1, 'rgba(40,20,40,0.4)'); x.fillStyle = g; x.fillRect(0, hz, 1920, 440); const bl = MG.blurred(x.canvas, 0); void bl; });
